<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from './api'
const props=defineProps({token:String,language:String,idle:Boolean})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const data=ref(null),settings=ref(null),dirty=ref(false),busy=ref(false),error=ref(''),notice=ref('')
let timer
const fields=[['min_pulse_ms','Минимальный импульс, мс','Eng qisqa impuls, ms','Minimum pulse, ms',1,10000],['max_pulse_ms','Максимальный импульс, мс','Eng uzun impuls, ms','Maximum pulse, ms',1,10000],['stuck_active_ms','Блокировка зависшего входа, мс','Qotib qolgan kirishni bloklash, ms','Stuck input lockout, ms',100,60000],['min_gap_ms','Минимальная пауза, мс','Eng qisqa tanaffus, ms','Minimum gap, ms',0,10000],['startup_idle_ms','Стабильный вход при запуске, мс','Ishga tushishda barqaror kirish, ms','Startup stable idle, ms',100,10000],['max_pulses_per_second','Лимит импульсов в секунду; 0 — без лимита','Bir soniyadagi impuls chegarasi; 0 — cheklanmagan','Pulses per second limit; 0 means unlimited',0,1000]]
const reasons={reader_failed:['Ошибка чтения уровня GPIO','GPIO darajasini o‘qish xatosi','GPIO level read failed'],reader_overflow:['Переполнена очередь GPIO — приём остановлен','GPIO navbati to‘lgan — qabul to‘xtatildi','GPIO queue overflow — cash input stopped'],stuck_active:['Вход слишком долго активен','Kirish juda uzoq faol','Input stuck active'],excessive_rate:['Слишком высокая частота','Chastota juda yuqori','Excessive pulse rate'],timestamp_invalid:['Неверное время события GPIO — приём остановлен','GPIO hodisasi vaqti noto‘g‘ri — qabul to‘xtatildi','Invalid GPIO timestamp — cash input stopped'],timestamp_order:['Нарушен порядок событий GPIO — приём остановлен','GPIO hodisalari tartibi buzilgan — qabul to‘xtatildi','GPIO events out of order — cash input stopped']}
function mark(){dirty.value=true;notice.value='';emit('dirty',true)}
async function load(){try{data.value=await api('/api/admin/service/bill-filter',{token:props.token});if(data.value.fault)notice.value='';if(!dirty.value)settings.value={...data.value.settings}}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{data.value=await api('/api/admin/service/bill-filter',{token:props.token,method:'POST',body:JSON.stringify(settings.value)});dirty.value=false;emit('dirty',false);settings.value={...data.value.settings};notice.value=tr('Сохранено на этом устройстве','Ushbu qurilmada saqlandi','Saved on this device')}catch(e){error.value=e.message}finally{busy.value=false}}
async function reset(){busy.value=true;error.value='';try{data.value=await api('/api/admin/service/bill-filter/reset',{token:props.token,method:'POST',body:'{}'});notice.value=tr('Вход разблокирован','Kirish blokdan chiqarildi','Input unlocked')}catch(e){error.value=e.message}finally{busy.value=false}}
function preset(event){settings.value={...data.value.presets[event.target.value]};mark()}
onMounted(()=>{load();timer=setInterval(load,2000)})
onUnmounted(()=>{clearInterval(timer);emit('dirty',false)})
</script>
<template><section class="card content bill-filter"><h2>{{tr('Фильтр импульсов купюроприёмника','Kupyura qabul qilgich impuls filtri','Bill acceptor pulse filter')}}</h2><p>{{tr('Настраивайте на пустом посту, не вставляя купюры. Считаются только полные импульсы. Сумма за импульс задаётся отдельно.','Bo‘sh postda, kupyura kiritmasdan sozlang. Faqat to‘liq impulslar hisoblanadi. Impuls summasi alohida sozlanadi.','Configure on an idle station without inserting bills. Only complete pulses are counted. Value per pulse is configured separately.')}}</p><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message success" role="status">{{notice}}</p><template v-if="data"><p v-if="!data.enabled" class="muted">{{tr('Денежный GPIO-вход отключён в профиле оборудования','Pul GPIO kirishi uskuna profilida o‘chirilgan','Cash GPIO input is disabled in the hardware profile')}}</p><template v-else><p :class="{'message error':data.fault}" role="status">{{data.fault?(reasons[data.fault]?tr(...reasons[data.fault]):data.fault):data.ready?tr('Вход готов','Kirish tayyor','Input ready'):tr('Ожидание стабильного входа','Barqaror kirish kutilmoqda','Waiting for stable input')}}</p><p>{{tr('Сырые импульсы / проверенные / записанные в журнал','Xom / tekshirilgan / jurnalga yozilgan impulslar','Raw / validated / journaled pulses')}}: {{data.raw_pulses}} / {{data.validated_pulses}} / {{data.published_pulses}}</p><p class="muted">{{tr('Сырые и проверенные — после запуска; журнал — за всё время.','Xom va tekshirilgan — ishga tushgandan beri; jurnal — jami.','Raw and validated are since startup; journaled is the lifetime total.')}}</p><p v-if="Object.keys(data.rejected||{}).length">{{tr('Отклонены','Rad etilgan','Rejected')}}: {{data.rejected}}</p><p v-if="data.diagnostics?.timestamp_source" class="muted">{{data.diagnostics.timestamp_source==='kernel'?tr('Время фронтов: ядро Linux','Front vaqti: Linux yadrosi','Edge timestamps: Linux kernel'):tr('Чтение уровня GPIO','GPIO darajasini o‘qish','GPIO level sampling')}}. {{tr('Максимальная задержка чтения / записи, мс','Eng katta o‘qish / yozish kechikishi, ms','Maximum read / journal delay, ms')}}: {{data.diagnostics.max_queue_delay_ms}} / {{data.diagnostics.max_commit_ms}}. {{tr('Повторные фронты','Takroriy frontlar','Repeated edges')}}: {{data.repeated_edges||0}}</p><p v-if="data.diagnostics?.reader==='level'" class="muted">{{tr('Максимальный промежуток выборки, мс / неоднозначные промежутки','Tanlashdagi eng katta oraliq, ms / noaniq oraliqlar','Maximum sampling gap, ms / uncertain gaps')}}: {{data.diagnostics.max_sample_gap_ms}} / {{data.diagnostics.uncertain_gaps}}</p><p class="muted">{{tr('Максимальный импульс ограничивает один сигнал, а не количество импульсов купюры. Длинный завершённый импульс отклоняется отдельно; зависший вход блокируется по отдельному порогу.','Eng uzun impuls bitta signalni cheklaydi, kupyura impulslari sonini emas. Uzoq tugallangan impuls alohida rad etiladi; qotib qolgan kirish alohida chegara bilan bloklanadi.','Maximum pulse limits one signal, not the number of pulses per bill. A completed long pulse is rejected separately; a stuck input uses its own lockout threshold.')}}</p><p v-if="data.samples?.length">{{tr('Последние длительности, мс','Oxirgi davomiyliklar, ms','Recent durations, ms')}}: {{data.samples.slice(-10).map(s=>s.width_ms).join(' · ')}}</p><form v-if="settings" @submit.prevent="save" @input="mark" @change="mark"><fieldset :disabled="busy||!idle"><label>{{tr('Профиль','Profil','Profile')}}<select @change="preset"><option disabled selected value="">{{tr('Выберите при необходимости','Zarur bo‘lsa tanlang','Select if needed')}}</option><option value="generic">{{tr('Широкий диапазон','Keng diapazon','Wide range')}}</option><option value="standard_50_100ms">{{tr('Импульсы 50–100 мс','50–100 ms impulslar','50–100 ms pulses')}}</option></select></label><div class="fields"><label v-for="[key,ru,uz,en,min,max] in fields" :key="key">{{tr(ru,uz,en)}}<input type="number" v-model.number="settings[key]" :min="min" :max="max" required step="1"/></label><label class="check"><input type="checkbox" v-model="settings.active_low"/>{{tr('Активный уровень — низкий','Faol daraja — past','Active-low signal')}}</label></div><button class="primary" :disabled="!dirty">{{tr('Сохранить фильтр','Filtrni saqlash','Save filter')}}</button></fieldset></form><button v-if="data.fault" class="quiet" :disabled="busy||!idle||data.active||dirty" @click="reset">{{tr('Сбросить ошибку после проверки контактов','Kontaktlar tekshirilgach xatoni tiklash','Reset fault after checking connections')}}</button><p class="muted">{{tr('Сброс не меняет денежный счётчик. Неисправный GND программный фильтр полностью не заменяет.','Tiklash pul hisoblagichini o‘zgartirmaydi. Dasturiy filtr nosoz GND o‘rnini to‘liq bosa olmaydi.','Reset does not change the money counter. Software cannot fully compensate for a faulty ground connection.')}}</p></template></template></section></template>
<style scoped>.bill-filter p{line-height:1.5}.bill-filter fieldset{border:0;padding:0}.bill-filter label{display:flex;flex-direction:column;gap:8px}.bill-filter .check{flex-direction:row}.bill-filter button{margin-top:18px}</style>
